package com.personal.assistant.module.tradingreview.service;
import com.personal.assistant.common.exception.*;import com.personal.assistant.module.tradingreview.dto.*;import com.personal.assistant.module.tradingreview.entity.*;import org.springframework.stereotype.Component;import java.math.*;import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*;
@Component public class TradeMetricsCalculator{private static final int S=4;public TradeMetrics calculate(List<TradingExecution> rows,BigDecimal latest){BigDecimal bought=BigDecimal.ZERO,sold=BigDecimal.ZERO,remaining=BigDecimal.ZERO,cost=BigDecimal.ZERO,realized=BigDecimal.ZERO,fees=BigDecimal.ZERO;LocalDateTime first=null,last=null;for(var row:rows.stream().sorted(Comparator.comparing(TradingExecution::getOccurredAt)).toList()){BigDecimal fee=n(row.getCommission()).add(n(row.getStampDuty())).add(n(row.getTransferFee()));fees=fees.add(fee);if("BUY".equals(row.getSide())){bought=bought.add(row.getQuantity());remaining=remaining.add(row.getQuantity());cost=cost.add(row.getQuantity().multiply(row.getPrice())).add(fee);if(first==null)first=row.getOccurredAt();}else if("SELL".equals(row.getSide())){if(row.getQuantity().compareTo(remaining)>0)throw new BusinessException(ErrorCode.VALIDATION_ERROR,"卖出数量不能超过持仓");BigDecimal avg=remaining.signum()==0?BigDecimal.ZERO:cost.divide(remaining,8,RoundingMode.HALF_UP);realized=realized.add(row.getQuantity().multiply(row.getPrice()).subtract(fee).subtract(row.getQuantity().multiply(avg)));remaining=remaining.subtract(row.getQuantity());cost=cost.subtract(row.getQuantity().multiply(avg));sold=sold.add(row.getQuantity());last=row.getOccurredAt();}}BigDecimal avg=remaining.signum()==0?BigDecimal.ZERO:cost.divide(remaining,S,RoundingMode.HALF_UP);BigDecimal unrealized=latest==null?BigDecimal.ZERO:remaining.multiply(latest.subtract(avg));BigDecimal invested=rows.stream().filter(x->"BUY".equals(x.getSide())).map(x->x.getQuantity().multiply(x.getPrice())).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal rate=invested.signum()==0?BigDecimal.ZERO:realized.add(unrealized).divide(invested,6,RoundingMode.HALF_UP).multiply(BigDecimal.valueOf(100));int days=first==null?0:(int)ChronoUnit.DAYS.between(first.toLocalDate(),(remaining.signum()==0&&last!=null?last:LocalDateTime.now()).toLocalDate());return new TradeMetrics(bought,sold,remaining,avg,realized.setScale(S,RoundingMode.HALF_UP),unrealized.setScale(S,RoundingMode.HALF_UP),fees.setScale(S,RoundingMode.HALF_UP),rate.setScale(S,RoundingMode.HALF_UP),days);}private BigDecimal n(BigDecimal v){return v==null?BigDecimal.ZERO:v;}}